import React from "react";
import { Link } from "react-router-dom";
import "../styles/Navbar.css"; // Fixed CSS path!

const Navbar = () => {
  return (
    <nav className="navbar">

      {/* Logo Area - Clicks back to Home ("/") */}
      <div className="logo">
        <Link to="/" style={{ color: "white", textDecoration: "none" }}>
          🌊 Garbage Detection
        </Link>
      </div>

      {/* Navigation Links */}
      <ul className="nav-links">
        <li>
          {/* Goes to the Home Route */}
          <Link to="/" style={{ color: "white", textDecoration: "none" }}>Home</Link>
        </li>
        <li>
          {/* Goes to the Home Route (Since your upload box is on the home page) */}
          <Link to="/" style={{ color: "white", textDecoration: "none" }}>Upload</Link>
        </li>
        <li>
          {/* Goes to the About Route */}
          <Link to="/about" style={{ color: "white", textDecoration: "none" }}>About</Link>
        </li>
      </ul>

    </nav>
  );
};

export default Navbar;
